std::string data = "ABCDEFGHIJK";

// Replace 5 chars at index 3 ("DEFGH")
// Source is data itself, starting index 4 ("FGH")
// High overlap (index 4 is shared/moved).

data.replace(
    3,    // Destination position
    5,    // Destination length
    data, // Source string (same object)
    4,    // Source start position
    3     // Source length
);

